using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using System.Threading;
namespace PZ3D {
 static class JavaComponentWorkflowTests {
  static int checks;
  static void Check(bool value,string message){if(!value)throw new Exception("FAIL: "+message);checks++;Console.WriteLine("PASS: "+message);}
  internal static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));}
  internal static void Jar(string file,string package,string version=null){Directory.CreateDirectory(Path.GetDirectoryName(file));if(File.Exists(file))File.Delete(file);using(var zip=ZipFile.Open(file,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry(package.Replace('.','/')+"/Main.class").Open()))writer.Write("fixture");if(version!=null)using(var writer=new StreamWriter(zip.CreateEntry("META-INF/MANIFEST.MF").Open()))writer.Write("Manifest-Version: 1.0\nImplementation-Version: "+version+"\n\n");}}
  internal sealed class Fixture {
   internal readonly string Root=Path.Combine(Path.GetTempPath(),"ozl-jwf-"+Guid.NewGuid().ToString("N").Substring(0,8));internal Engine E;internal JavaComponents Manager;
   internal Fixture(){E=new Engine(Path.Combine(Root,"steam","steamapps","common","PZ"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true);Put(E.Config,"{\"vmArgs\":[\"-agentlib:zbNative\",\"-Duser.home="+Root.Replace("\\","\\\\")+"/home\"]}");Put(Path.Combine(E.Game,"version.txt"),"42.21");Put(Path.Combine(E.Game,"ProjectZomboid64.exe"),"fixture");Put(Path.Combine(E.Game,"zbNative.dll"),"fixture");Jar(Path.Combine(E.Game,"ZombieBuddy.jar"),"buddy","3.0.0");Put(E.Mods,"VERSION = 1,\nmods\n{\n mod = ZombieBuddy,\n mod = Unrelated,\n}\nmaps\n{\n map = KeepMap,\n}\ncustom = keep\n");Manager=new JavaComponents(E);}
   internal string Add(string id,string requires="",bool java=true,string item=null,bool common=false){string root=item==null?Path.Combine(E.User,"mods",id):Path.Combine(E.Workshop,item,"mods",id);string active=Path.Combine(root,common?"common":"42");Put(Path.Combine(active,"mod.info"),"id="+id+"\nname="+id+"\nrequire="+requires+"\n"+(java?"javaPkgName=test."+id+"\njavaJarFile=media/java/client/main.jar\n":""));if(java)Jar(Path.Combine(active,"media/java/client/main.jar"),"test."+id);return root;}
   internal string[] Mods(){return SaveProfiles.DefaultMods(SaveProfiles.DefaultBytes(E)).Select(x=>x.TrimStart('\\')).ToArray();}
  }
  static object Workflow(Fixture f,Action<string,Action<int,string>,CancellationToken> download=null,Func<string,Action<int,string>,CancellationToken,string> resolve=null,Func<string,string> known=null,Action<int,string> progress=null){var type=typeof(Engine).Assembly.GetType("PZ3D.JavaComponentWorkflow");Check(type!=null,"downloaded standard Java components have an install workflow");return Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{f.E,f.Manager,download,resolve,known,progress},null);}
  static Dictionary<string,object> Run(object w,string method,string value,CancellationToken token){try{var result=w.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(w,new object[]{value,true,token});var json=new System.Web.Script.Serialization.JavaScriptSerializer();return json.Deserialize<Dictionary<string,object>>(json.Serialize(result));}catch(TargetInvocationException ex){throw ex.InnerException;}}
  static string Status(Dictionary<string,object> result){return Convert.ToString(result["status"]);}
  static void Dependencies(){var f=new Fixture();f.Add("LocalJava","LocalLua");f.Add("LocalLua","",false);int downloads=0,resolved=0;var stages=new List<string>();var w=Workflow(f,(id,p,t)=>{downloads++;if(id=="999001")f.Add("Requested","LocalJava,Remote,LocalLua",true,id);else if(id=="999002")f.Add("Remote","LocalLua",false,id);else throw new Exception("unexpected download");},(id,p,t)=>{Check(id=="Remote","only the missing exact dependency is resolved");resolved++;return "999002";},null,(n,t)=>stages.Add(t));var result=Run(w,"Install","999001",CancellationToken.None);Check(Status(result)=="completed","single downloaded Java mod automatically enables dependencies");Check(f.Mods().SequenceEqual(new[]{"ZombieBuddy","LocalLua","LocalJava","Remote","Requested","Unrelated"}),"local Java, Lua, downloaded dependency enabled once in dependency order");Check(downloads==2&&resolved==1,"missing downloadable dependency is downloaded and re-read once");Check(File.ReadAllText(f.E.Mods).Contains("map = KeepMap")&&File.ReadAllText(f.E.Mods).Contains("custom = keep"),"default list preserves unrelated map and author fields");Check(stages.Any(s=>s.Contains("下载"))&&stages.Any(s=>s.Contains("识别"))&&stages.Any(s=>s.Contains("依赖"))&&stages.Any(s=>s.Contains("启用")),"progress reports actual workflow stages");}
  static void Bundle(){var f=new Fixture();byte[] before=File.ReadAllBytes(f.E.Mods);var w=Workflow(f,(id,p,t)=>{f.Add("AlternativeA","",true,id);f.Add("AlternativeB","",true,id);});var result=Run(w,"Install","999003",CancellationToken.None);Check(Status(result)=="selectionRequired"&&((System.Collections.IEnumerable)result["rows"]).Cast<object>().Count()==2,"multi Java bundle returns selectable inventory rows");Check(before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"bundle does not auto-enable alternatives");var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="AlternativeB");Check(Status(Run(w,"Enable",row.token,CancellationToken.None))=="completed"&&f.Mods().Contains("AlternativeB")&&!f.Mods().Contains("AlternativeA"),"selection enables only the chosen bundle submod");}
  static void Cycle(){var f=new Fixture();f.Add("CycleA","CycleB");f.Add("CycleB","CycleA");byte[] before=File.ReadAllBytes(f.E.Mods);var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="CycleA");var result=Run(Workflow(f),"Enable",row.token,CancellationToken.None);Check(Status(result)=="unresolved"&&Convert.ToString(result["message"]).Contains("CycleA")&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"cycle names the unresolved component before applying any default edits");}
  static void Cancellation(){var f=new Fixture();var c=new CancellationTokenSource();byte[] before=File.ReadAllBytes(f.E.Mods);var w=Workflow(f,(id,p,t)=>{f.Add("Cancelled","",true,id);c.Cancel();});var result=Run(w,"Install","999004",c.Token);Check(Status(result)=="cancelled"&&Convert.ToBoolean(result["cancelled"])&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"download cancellation retains downloaded files without enabling them");}
  static void CommonOnly(){var f=new Fixture();f.Add("CommonOnly","",true,"999011",true);var result=Run(Workflow(f,(id,p,t)=>{}),"Install","999011",CancellationToken.None);Check(Status(result)=="completed"&&f.Mods().Contains("CommonOnly"),"common-only Java layout can be recognized and enabled");}
  static void Numbered(){foreach(string buddy in new[]{"3.0.0","2.9.0"}){var f=new Fixture();Jar(Path.Combine(f.E.Game,"ZombieBuddy.jar"),"buddy",buddy);string root=f.Add("Numbered"),active=Path.Combine(root,"42");Put(Path.Combine(active,"mod.info"),"id=Numbered\njavaPkgName=test.Numbered\njavaJarFile=media/java/client/main.jar\nZBVersionMax=2.9.9\njavaJarFile7=media/java/client/third.jar\nZBVersionMin7=3.0.0\njavaJarFile2=media/java/client/second.jar\nZBVersionMin2=3.0.0\n");Jar(Path.Combine(active,"media/java/client/second.jar"),"test.Numbered");Jar(Path.Combine(active,"media/java/client/third.jar"),"wrong.package");var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="Numbered");var result=Run(Workflow(f),"Enable",row.token,CancellationToken.None);Check(Status(result)=="completed",buddy+" selects first compatible numeric JAR candidate and compatible bound pair");}}
  static void PartialCancel(){var f=new Fixture();f.Add("CancelRoot","LuaFirst");f.Add("LuaFirst","",false);var cancel=new CancellationTokenSource();var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="CancelRoot");var w=Workflow(f,null,null,null,(n,t)=>{if(t.Contains("正在启用")&&t.EndsWith(" · CancelRoot"))cancel.Cancel();});var result=Run(w,"Enable",row.token,cancel.Token);Check(Status(result)=="cancelled"&&f.Mods().Contains("LuaFirst")&&!f.Mods().Contains("CancelRoot"),"cancellation during apply preserves completed Lua dependency without enabling target");Check(((System.Collections.IEnumerable)result["enabled"]).Cast<string>().Contains("LuaFirst")&&Convert.ToBoolean(result["changed"]),"partial cancellation reports actual enabled dependency and changed state");}
  static void LaunchReconcile(){var f=new Fixture();int steamReads=0;var e=new Engine(f.E.Game,f.E.User,f.E.Data,true,()=>{steamReads++;throw new Exception("must not inspect Steam on no-record launch");});var type=typeof(Engine).Assembly.GetType("PZ3D.JavaComponentWorkflow");var method=type.GetMethod("ReconcileBeforeLaunch",BindingFlags.Static|BindingFlags.NonPublic);Check(method!=null,"production launch has a reconciliation entry point");var result=(JavaComponents.Result)method.Invoke(null,new object[]{e,CancellationToken.None,null});Check(result.status=="unchanged"&&steamReads==0,"no-record launch reconciliation does not scan workshop or read Steam");}
  static void FrameworkOrder(){var f=new Fixture();f.Add("ImplicitFramework");var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="ImplicitFramework");var result=Run(Workflow(f),"Enable",row.token,CancellationToken.None);Check(Status(result)=="completed"&&f.Mods().SequenceEqual(new[]{"ZombieBuddy","ImplicitFramework","Unrelated"}),"implicit Java framework remains before selected Java components even when already configured");}
  static void LateFrameworkDisabled(){LateFramework(false);}
  static void LateFrameworkReady(){LateFramework(true);}
  static void LateFramework(bool ready){var f=new Fixture();f.Add("LocalJava");f.Add("LateTarget","LocalJava,ZombieBuddy");f.Add("ZombieBuddy","LuaBeforeBuddy",false);f.Add("LuaBeforeBuddy","",false);if(!ready)Put(f.E.Mods,Encoding.UTF8.GetString(SaveProfiles.ReplaceDefaultMods(SaveProfiles.DefaultBytes(f.E),new[]{"Unrelated"})));int installs=0;var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="LateTarget");var result=Run(Workflow(f,null,null,key=>{Check(key=="buddy","implicit prerequisite uses Buddy specialized installer");Check(f.Mods().Contains("LuaBeforeBuddy"),"framework's declared Lua dependency is applied before its installer");installs++;Put(f.E.Mods,Encoding.UTF8.GetString(SaveProfiles.ReplaceDefaultMods(SaveProfiles.DefaultBytes(f.E),f.Mods().Concat(new[]{"ZombieBuddy"}).ToArray())));return "已启用 Buddy";}),"Enable",row.token,CancellationToken.None);Check(Status(result)=="completed",(ready?"ready":"disabled")+" framework supports Java dependency before explicit late Buddy");Check(f.Mods().SequenceEqual(new[]{"LuaBeforeBuddy","ZombieBuddy","LocalJava","LateTarget","Unrelated"}),"every Java consumer follows Buddy while framework's own dependency remains first");Check(installs==(ready?0:1)&&f.Mods().Distinct().Count()==f.Mods().Length,"framework installer and dependency application occur at most once");}
  static void ImplicitFrameworkCycle(){var f=new Fixture();f.Add("CycleLocalJava");f.Add("CycleTarget","CycleLocalJava,ZombieBuddy");f.Add("ZombieBuddy","CycleLocalJava",false);byte[] before=File.ReadAllBytes(f.E.Mods);int installs=0;var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="CycleTarget");var result=Run(Workflow(f,null,null,key=>{installs++;return "unexpected";}),"Enable",row.token,CancellationToken.None);Check(Status(result)=="unresolved"&&Convert.ToString(result["message"]).Contains("循环"),"implicit Buddy edge detects cycle through framework's own Java dependency");Check(installs==0&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"implicit framework cycle applies no installer or default-list changes");}
  static void MissingIdentity(){var f=new Fixture();f.Add("NeedsExact","Exact");byte[] before=File.ReadAllBytes(f.E.Mods);var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="NeedsExact");var result=Run(Workflow(f,(id,p,t)=>f.Add("WrongId","",false,id),(id,p,t)=>"999012"),"Enable",row.token,CancellationToken.None);Check(Status(result)=="unresolved"&&Convert.ToString(result["message"]).Contains("Exact")&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"downloaded dependency is re-read and wrong exact ID never enabled");}
  static void KnownAdapter(){var f=new Fixture();f.Add("NeedsKnown","Viewpoint");int calls=0;var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="NeedsKnown");var result=Run(Workflow(f,null,null,key=>{Check(key=="viewpoint","known dependency uses specialized installer");calls++;Put(f.E.Mods,File.ReadAllText(f.E.Mods).Replace("mod = Unrelated,","mod = Unrelated,\n mod = AdapterExtra,\n mod = Viewpoint,"));return "已安装";}),"Enable",row.token,CancellationToken.None);Check(Status(result)=="completed"&&calls==1&&f.Mods().Contains("AdapterExtra"),"specialized installer additions survive later default-list apply");}
  static void FailedAdapter(){var f=new Fixture();f.Add("NeedsFailure","Viewpoint");var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="NeedsFailure");var result=Run(Workflow(f,null,null,key=>{Put(f.E.Mods,File.ReadAllText(f.E.Mods).Replace("mod = Unrelated,","mod = Unrelated,\n mod = AdapterPartial,"));return "[失败] Viewpoint 下载未完成";}),"Enable",row.token,CancellationToken.None);Check(Status(result)=="unresolved"&&!f.Mods().Contains("NeedsFailure")&&f.Mods().Contains("AdapterPartial"),"specialized installer failure retains actual partial side effects");Check(Convert.ToBoolean(result["changed"])&&((System.Collections.IEnumerable)result["enabled"]).Cast<string>().Contains("AdapterPartial"),"failed adapter reports actual applied IDs instead of unchanged");}
  static void Frozen(){var f=new Fixture();byte[] original=File.ReadAllBytes(f.E.Mods);f.E.FrozenEnvironment=new SaveEnvironmentRecord{RootPath=f.Root};Put(f.E.Mods,Encoding.UTF8.GetString(original));int downloads=0;var result=Run(Workflow(f,(id,p,t)=>downloads++),"Install","999013",CancellationToken.None);Check(Status(result)=="failed"&&downloads==0,"frozen environment refuses install before downloading");}
  static void RecognitionCancel(){var f=new Fixture();for(int i=0;i<4;i++)f.Add("Scan"+i);var c=new CancellationTokenSource();int observed=0;f.Manager=new JavaComponents(f.E,(n,text)=>{if(text.Contains("元数据")){observed++;if(observed==1)c.Cancel();}});var result=Run(Workflow(f),"Enable",new string('a',64),c.Token);Check(Status(result)=="cancelled"&&observed==1&&!f.Mods().Any(id=>id.StartsWith("Scan")),"recognition exposes actual metadata counts and cancels during scanning");}
  static void PackageRows(){var f=new Fixture();Put(f.E.Config,File.ReadAllText(f.E.Config).Replace("-agentlib:zbNative","-javaagent:foreign.jar"));var result=Run(Workflow(f,(id,p,t)=>f.Add("ScopedPackage","",true,id)),"Install","999015",CancellationToken.None);Check(Status(result)!="selectionRequired"&&((System.Collections.IEnumerable)result["rows"]).Cast<object>().Count()==1,"downloaded package rows exclude unrelated startup agents");}
  static void LockedDefault(){var f=new Fixture();var w=Workflow(f);Dictionary<string,object> result=null;bool escaped=false;using(var file=new FileStream(f.E.Mods,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){try{result=Run(w,"Enable",new string('a',64),CancellationToken.None);}catch(IOException){escaped=true;}}Check(!escaped&&result!=null&&Status(result)=="failed"&&!Convert.ToBoolean(result["changed"])&&!((System.Collections.IEnumerable)result["enabled"]).Cast<object>().Any(),"locked default list returns typed failure without claiming baseline differences");}
  static void FinalRows(){var f=new Fixture();f.Add("FreshRows");var row=((JavaComponents.Inventory)f.Manager.List()).rows.Single(r=>r.modId=="FreshRows");var result=Run(Workflow(f),"Enable",row.token,CancellationToken.None);var final=((System.Collections.IEnumerable)result["rows"]).Cast<Dictionary<string,object>>().Single(r=>Convert.ToString(r["modId"])=="FreshRows");Check(Convert.ToBoolean(final["defaultEnabled"])&&Convert.ToBoolean(final["enabled"]),"successful response includes refreshed actual enabled package rows");}
  static void Host(){foreach(string action in new[]{"javaComponentsInstall","javaComponentsEnable","javaComponentsReconcile"}){var p=new Dictionary<string,object>{{"confirmed",true}};if(action=="javaComponentsInstall")p["id"]="999001";if(action=="javaComponentsEnable")p["token"]=new string('a',64);var json=new System.Web.Script.Serialization.JavaScriptSerializer();Check(ModernHostPolicy.Validate("https://orange.local/index.html",json.Serialize(new{id="test",action=action,payload=p}))!=null,"host accepts strict "+action);Check(!ModernController.NativeReads.Contains(action),action+" is a mutation");p["path"]="unexpected";bool rejected=false;try{ModernHostPolicy.Validate("https://orange.local/index.html",json.Serialize(new{id="test",action=action,payload=p}));}catch{rejected=true;}Check(rejected,action+" rejects extra fields");}}
  public static int Main(){try{foreach(var test in new Action[]{LateFrameworkDisabled,LateFrameworkReady,ImplicitFrameworkCycle,FinalRows,LockedDefault,PackageRows,RecognitionCancel,FrameworkOrder,MissingIdentity,KnownAdapter,FailedAdapter,Frozen,LaunchReconcile,CommonOnly,Numbered,PartialCancel,Dependencies,Bundle,Cycle,Cancellation,Host})test();Console.WriteLine("JAVA WORKFLOW PASSED: "+checks);return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
 }
